import{_ as d,a0 as r,w as a,s as c,ao as m,I as s,x as t,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse(`{"title":"RHCSA 系列（六）: 使用 Parted 和 SSM 來配置和加密系統存儲 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（六）: 使用 Parted 和 SSM 來配置和加密系統存儲 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（六）: 使用 Parted 和 SSM 來配置和加密系統存儲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（六）: 使用 Parted 和 SSM 來配置和加密系統存儲 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 06--Using 'Parted' and 'SSM' to Configure and Encrypt System Storage","title":"RHCSA 系列（六）: 使用 Parted 和 SSM 來配置和加密系統存儲","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 06--Using 'Parted' and 'SSM' to Configure and Encrypt System Storage.md","filePath":"[post].md"}`),i={name:"RHCSA Series/RHCSA Series--Part 06--Using 'Parted' and 'SSM' to Configure and Encrypt System Storage.md"};function l(v,e,g,u,S,_){const p=r("Link");return a(),c("div",null,[e[13]||(e[13]=m(`<h1 id="rhcsa-系列-六-使用-parted-和-ssm-來配置和加密系統存儲" tabindex="-1">RHCSA 系列（六）: 使用 Parted 和 SSM 來配置和加密系統存儲 <a class="header-anchor" href="#rhcsa-系列-六-使用-parted-和-ssm-來配置和加密系統存儲" aria-label="Permalink to “RHCSA 系列（六）: 使用 Parted 和 SSM 來配置和加密系統存儲”">​</a></h1><p>在本篇文章中，我們將討論在 RHEL 7 中如何使用傳統的工具來設置和配置本地系統存儲，並介紹系統存儲管理器（也稱為 SSM），它將極大地簡化上面的任務。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Configure-and-Encrypt-System-Storage.png" alt="配置和加密系統存儲"></p><p><em>RHCSA: 配置和加密系統存儲 – Part 6</em></p><p>請注意，我們將在這篇文章中展開這個話題，但由於該話題的寬泛性，我們將在下一期中繼續介紹有關它的描述和使用。</p><h3 id="在-rhel-7-中創建和修改分區" tabindex="-1">在 RHEL 7 中創建和修改分區 <a class="header-anchor" href="#在-rhel-7-中創建和修改分區" aria-label="Permalink to “在 RHEL 7 中創建和修改分區”">​</a></h3><p>在 RHEL 7 中， parted 是默認的用來處理分區的程序，且它允許你：</p><ul><li>展示當前的分區表</li><li>操縱（擴大或縮小分區的大小）現有的分區</li><li>利用空餘的磁盤空間或額外的物理存儲設備來創建分區</li></ul><p>強烈建議你在試圖增加一個新的分區或對一個現有分區進行更改前，你應當確保該設備上沒有任何一個分區正在使用（<code>umount /dev/分區</code>），且假如你正使用設備的一部分來作為 swap 分區，在進行上面的操作期間，你需要將它禁用（<code>swapoff -v /dev/分區</code>） 。</p><p>實施上面的操作的最簡單的方法是使用一個安裝介質例如一個 RHEL 7 的 DVD 或 USB 安裝盤以急救模式啓動 RHEL（<code>Troubleshooting</code> → <code>Rescue a Red Hat Enterprise Linux system</code>），然後當讓你選擇一個選項來掛載現有的 Linux 安裝時，選擇“跳過”這個選項，接着你將看到一個命令列提示符，在其中你可以像下圖顯示的那樣開始鍵入與在一個未被使用的物理設備上創建一個正常的分區時所用的相同的命令。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/RHEL-7-Rescue-Mode.png" alt="RHEL 7 急救模式"></p><p><em>RHEL 7 急救模式</em></p><p>要啓動 parted，只需鍵入：</p><pre><code># parted /dev/sdb
</code></pre><p>其中 <code>/dev/sdb</code> 是你將要創建新分區所在的設備；然後鍵入 <code>print</code> 來顯示當前設備的分區表：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Create-New-Partition.png" alt="創建新的分區"></p><p><em>創建新的分區</em></p><p>正如你所看到的那樣，在這個例子中，我們正在使用一個 5 GB 的虛擬驅動器。現在我們將要創建一個 4 GB 的主分區，然後將它格式化為 xfs 文件系統，它是 RHEL 7 中默認的文件系統。</p><p>你可以從一系列的文件系統中進行選擇。你將需要使用 <code>mkpart</code> 來手動地創建分區，接着和平常一樣，用 <code>mkfs.類型</code> 來對分區進行格式化，因為 <code>mkpart</code> 並不支持許多現代的文件系統的到即開即用。</p><p>在下面的例子中，我們將為設備設定一個標記，然後在 <code>/dev/sdb</code> 上創建一個主分區 <code>(p)</code>，它從設備的 0% 開始，並在 4000MB(4 GB) 處結束。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Label-Partition.png" alt="在 Linux 中設定分區名稱"></p><p><em>標記分區的名稱</em></p><p>接下來，我們將把分區格式化為 xfs 文件系統，然後再次打印出分區表，以此來確保更改已被應用。</p><pre><code># mkfs.xfs /dev/sdb1
# parted /dev/sdb print
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Format-Partition-in-Linux.png" alt="在 Linux 中格式化分區"></p><p><em>格式化分區為 XFS 文件系統</em></p><p>對於舊一點的文件系統，在 parted 中你可以使用 <code>resize</code> 命令來改變分區的大小。不幸的是，這隻適用於 ext2, fat16, fat32, hfs, linux-swap, 和 reiserfs （若 libreiserfs 已被安裝）。</p><p>因此，改變分區大小的唯一方式是刪除它然後再創建它（所以，確保你對你的數據做了完整的備份！）。毫無疑問，在 RHEL 7 中默認的分區方案是基於 LVM 的。</p><p>使用 parted 來移除一個分區，可以用：</p><pre><code># parted /dev/sdb print
# parted /dev/sdb rm 1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Remove-Partition-in-Linux.png" alt="在 Linux 中移除分區"></p><p><em>移除或刪除分區</em></p><h3 id="邏輯卷管理-lvm" tabindex="-1">邏輯卷管理(LVM) <a class="header-anchor" href="#邏輯卷管理-lvm" aria-label="Permalink to “邏輯卷管理(LVM)”">​</a></h3><p>一旦一個磁盤被分好了分區，再去更改分區的大小就是一件困難或冒險的事了。基於這個原因，假如我們計劃在我們的系統上對分區的大小進行更改，我們應當考慮使用 LVM 的可能性，而不是使用傳統的分區系統。這樣多個物理設備可以組成一個邏輯組，以此來存放任意數目的邏輯卷，而邏輯卷的增大或減少不會帶來任何麻煩。</p><p>簡單來説，你會發現下面的示意圖對記住 LVM 的基礎架構或許有用。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/LVM-Diagram.png" alt="LVM 的基本架構"></p><p><em>LVM 的基本架構</em></p><h4 id="創建物理卷-卷組和邏輯卷" tabindex="-1">創建物理卷，卷組和邏輯卷 <a class="header-anchor" href="#創建物理卷-卷組和邏輯卷" aria-label="Permalink to “創建物理卷，卷組和邏輯卷”">​</a></h4><p>遵循下面的步驟是為了使用傳統的卷管理工具來設置 LVM。由於你可以通過閲讀這個網站上的 LVM 系列來擴展這個話題，我將只是概要的介紹設置 LVM 的基本步驟，然後與使用 SSM 來實現相同功能做個比較。</p><p><strong>注</strong>: 我們將使用整個磁盤 <code>/dev/sdb</code> 和 <code>/dev/sdc</code> 來作為物理卷（PV），但是否執行相同的操作完全取決於你。</p><p><strong>1. 使用 /dev/sdb 和 /dev/sdc 中 100% 的可用磁盤空間來創建分區 <code>/dev/sdb1</code> 和 <code>/dev/sdc1</code>：</strong></p><pre><code># parted /dev/sdb print
# parted /dev/sdc print
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Create-New-Partitions.png" alt="創建新分區"></p><p><em>創建新分區</em></p><p><strong>2. 分別在 /dev/sdb1 和 /dev/sdc1 上共創建 2 個物理卷。</strong></p><pre><code># pvcreate /dev/sdb1
# pvcreate /dev/sdc1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Create-Physical-Volumes.png" alt="創建兩個物理卷"></p><p><em>創建兩個物理卷</em></p><p>記住，你可以使用 pvdisplay /dev/sd{b,c}1 來顯示有關新建的物理卷的信息。</p><p><strong>3. 在上一步中創建的物理卷之上創建一個卷組（VG）：</strong></p><pre><code># vgcreate tecmint_vg /dev/sd{b,c}1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Create-Volume-Group.png" alt="在 Linux 中創建卷組"></p><p><em>創建卷組</em></p><p>記住，你可使用 vgdisplay tecmint_vg 來顯示有關新建的卷組的信息。</p><p><strong>4. 像下面那樣，在卷組 tecmint_vg 之上創建 3 個邏輯卷（LV）：</strong></p><pre><code># lvcreate -L 3G -n vol01_docs tecmint_vg       [vol01_docs → 3 GB]
# lvcreate -L 1G -n vol02_logs tecmint_vg       [vol02_logs → 1 GB]
# lvcreate -l 100%FREE -n vol03_homes tecmint_vg    [vol03_homes → 6 GB]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Create-Logical-Volumes.png" alt="在 LVM 中創建邏輯卷"></p><p><em>創建邏輯卷</em></p><p>記住，你可以使用 lvdisplay tecmint_vg 來顯示有關在 tecmint_vg 之上新建的邏輯卷的信息。</p><p><strong>5. 格式化每個邏輯卷為 xfs 文件系統格式（假如你計劃在以後將要縮小卷的大小，請別使用 xfs 文件系統格式！）：</strong></p><pre><code># mkfs.xfs /dev/tecmint_vg/vol01_docs
# mkfs.xfs /dev/tecmint_vg/vol02_logs
# mkfs.xfs /dev/tecmint_vg/vol03_homes
</code></pre><p><strong>6. 最後，掛載它們：</strong></p><pre><code># mount /dev/tecmint_vg/vol01_docs /mnt/docs
# mount /dev/tecmint_vg/vol02_logs /mnt/logs
# mount /dev/tecmint_vg/vol03_homes /mnt/homes
</code></pre><h4 id="移除邏輯卷-卷組和物理卷" tabindex="-1">移除邏輯卷，卷組和物理卷 <a class="header-anchor" href="#移除邏輯卷-卷組和物理卷" aria-label="Permalink to “移除邏輯卷，卷組和物理卷”">​</a></h4><p><strong>7.現在我們將進行與剛才相反的操作並移除邏輯卷、卷組和物理卷：</strong></p><pre><code># lvremove /dev/tecmint_vg/vol01_docs
# lvremove /dev/tecmint_vg/vol02_logs
# lvremove /dev/tecmint_vg/vol03_homes
# vgremove /dev/tecmint_vg
# pvremove /dev/sd{b,c}1
</code></pre><p><strong>8. 現在，讓我們來安裝 SSM，我們將看到如何只用一步就完成上面所有的操作！</strong></p><pre><code># yum update &amp;&amp; yum install system-storage-manager
</code></pre><p>我們將和上面一樣，使用相同的名稱和大小：</p><pre><code># ssm create -s 3G -n vol01_docs -p tecmint_vg --fstype ext4 /mnt/docs /dev/sd{b,c}1
# ssm create -s 1G -n vol02_logs -p tecmint_vg --fstype ext4 /mnt/logs /dev/sd{b,c}1
# ssm create -n vol03_homes -p tecmint_vg --fstype ext4 /mnt/homes /dev/sd{b,c}1
</code></pre><p>是的! SSM 可以讓你：</p><ul><li>初始化塊設備來作為物理卷</li><li>創建一個卷組</li><li>創建邏輯卷</li><li>格式化邏輯卷，以及</li><li>只使用一個命令來掛載它們</li></ul><p><strong>9. 現在，我們可以使用下面的命令來展示有關物理卷、卷組或邏輯卷的信息：</strong></p><pre><code># ssm list dev
# ssm list pool
# ssm list vol
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Display-LVM-Information.png" alt="檢查有關物理卷、卷組或邏輯卷的信息"></p><p><em>檢查有關物理卷、卷組或邏輯卷的信息</em></p><p><strong>10. 正如我們知道的那樣， LVM 的一個顯著的特點是可以在不停機的情況下更改（增大或縮小）邏輯卷的大小：</strong></p><p>假定在 vol02_logs 上我們用盡了空間，而 vol03_homes 還留有足夠的空間。我們將把 vol03_homes 的大小調整為 4 GB，並使用剩餘的空間來擴展 vol02_logs：</p><pre><code># ssm resize -s 4G /dev/tecmint_vg/vol03_homes
</code></pre><p>再次運行 <code>ssm list pool</code>，並記錄 tecmint_vg 中的剩餘空間的大小：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-LVM-Free-Space.png" alt="查看卷的大小"></p><p><em>查看卷的大小</em></p><p>然後執行：</p><pre><code># ssm resize -s+1.99 /dev/tecmint_vg/vol02_logs
</code></pre><p><strong>注</strong>: 在 <code>-s</code> 後的加號暗示特定值應該被加到當前值上。</p><p><strong>11. 使用 ssm 來移除邏輯卷和卷組也更加簡單，只需使用：</strong></p><pre><code># ssm remove tecmint_vg
</code></pre><p>這個命令將返回一個提示，詢問你是否確認刪除卷組和它所包含的邏輯卷：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Remove-LV-VG.png" alt="移除邏輯卷和卷組"></p><p><em>移除邏輯卷和卷組</em></p><h3 id="管理加密的卷" tabindex="-1">管理加密的卷 <a class="header-anchor" href="#管理加密的卷" aria-label="Permalink to “管理加密的卷”">​</a></h3><p>SSM 也給系統管理員提供了為新的或現存的卷加密的能力。首先，你將需要安裝 cryptsetup 軟件包：</p><pre><code># yum update &amp;&amp; yum install cryptsetup
</code></pre><p>然後寫出下面的命令來創建一個加密卷，你將被要求輸入一個密碼來增強安全性：</p><pre><code># ssm create -s 3G -n vol01_docs -p tecmint_vg --fstype ext4 --encrypt luks /mnt/docs /dev/sd{b,c}1
# ssm create -s 1G -n vol02_logs -p tecmint_vg --fstype ext4 --encrypt luks /mnt/logs /dev/sd{b,c}1
# ssm create -n vol03_homes -p tecmint_vg --fstype ext4 --encrypt luks /mnt/homes /dev/sd{b,c}1
</code></pre><p>我們的下一個任務是往 /etc/fstab 中添加條目來讓這些邏輯卷在啓動時可用，而不是使用設備識別編號(/dev/something)。</p><p>我們將使用每個邏輯卷的 UUID （使得當我們添加其他的邏輯卷或設備後，我們的設備仍然可以被唯一的標記），而我們可以使用 blkid 應用來找到它們的 UUID：</p><pre><code># blkid -o value UUID /dev/tecmint_vg/vol01_docs
# blkid -o value UUID /dev/tecmint_vg/vol02_logs
# blkid -o value UUID /dev/tecmint_vg/vol03_homes
</code></pre><p>在我們的例子中：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Logical-Volume-UUID.png" alt="找到邏輯卷的 UUID"></p><p><em>找到邏輯卷的 UUID</em></p><p>接着，使用下面的內容來創建 /etc/crypttab 文件(請更改 UUID 來適用於你的設置)：</p><pre><code>docs UUID=ba77d113-f849-4ddf-8048-13860399fca8 none
logs UUID=58f89c5a-f694-4443-83d6-2e83878e30e4 none
homes UUID=92245af6-3f38-4e07-8dd8-787f4690d7ac none
</code></pre><p>然後在 /etc/fstab 中添加如下的條目。請注意到 device_name (/dev/mapper/device_name) 是出現在 /etc/crypttab 中第一列的映射標識：</p><pre><code># Logical volume vol01_docs:
/dev/mapper/docs        /mnt/docs       ext4    defaults        0       2
# Logical volume vol02_logs
/dev/mapper/logs        /mnt/logs       ext4    defaults        0       2
# Logical volume vol03_homes
/dev/mapper/homes       /mnt/homes      ext4    defaults        0       2
</code></pre><p>現在重啓（<code>systemctl reboot</code>），則你將被要求為每個邏輯卷輸入密碼。隨後，你可以通過檢查相應的掛載點來確保掛載操作是否成功：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Verify-LV-Mount-Points.png" alt="確保邏輯卷掛載點"></p><p><em>確保邏輯卷掛載點</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這篇教程中，我們開始探索如何使用傳統的卷管理工具和 SSM 來設置和配置系統存儲，SSM 也在一個軟件包中集成了文件系統和加密功能。這使得對於任何系統管理員來説，SSM 是一個非常有價值的工具。</p><p>假如你有任何的問題或評論，請讓我們知曉 – 請隨意使用下面的評論框來與我們保存聯繫！</p><hr>`,112)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),o(p,{href:"http://www.tecmint.com/rhcsa-exam-create-format-resize-delete-and-encrypt-partitions-in-linux/"},{default:n(()=>[...e[0]||(e[0]=[t("http://www.tecmint.com/rhcsa-exam-create-format-resize-delete-and-encrypt-partitions-in-linux/",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=t("作者：",-1)),o(p,{href:"http://www.tecmint.com/author/gacanepa/"},{default:n(()=>[...e[2]||(e[2]=[t("Gabriel Cánepa",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),o(p,{href:"https://github.com/FSSlc"},{default:n(()=>[...e[3]||(e[3]=[t("FSSlc",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),o(p,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=t("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),o(p,{href:"https://linux.cn/"},{default:n(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const L=d(i,[["render",l]]);export{h as __pageData,L as default};
